    array("number" => 7, "name" => "Season 7", "rating" => 8.6, "episodes" => array(
        array("id" => "s7e1", "season" => 7, "number" => 1, "name" => "In the Nick of Time! A Big-Time Maverick from the West!", "airdate" => "4 May 2024", "runtime" => 25, "rating" => 9, "summary" => "As jailbreakers run rampant in Japan, Star and Stripe flies from the U.S. to Japan to help and finds Shigaraki waiting for her in the middle of her flight path.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612761.jpg"),
        array("id" => "s7e2", "season" => 7, "number" => 2, "name" => "Specter", "airdate" => "11 May 2024", "runtime" => 25, "rating" => 9.3, "summary" => "The fight between Star and Stripe and Shigaraki is coming to an end, but Star has one more trick up her sleeve with New Order.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612760.jpg"),
        array("id" => "s7e3", "season" => 7, "number" => 3, "name" => "Villain", "airdate" => "18 May 2024", "runtime" => 25, "rating" => 9, "summary" => "After failing to steal Star's Quirk, New Order, and losing many other Quirks, Shigaraki and All For One prepare for their next move. Who is the traitor at U.A.?!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612762.jpg"),
        array("id" => "s7e4", "season" => 7, "number" => 4, "name" => "The Story of How We All Became Heroes", "airdate" => "25 May 2024", "runtime" => 25, "rating" => 8, "summary" => "Due to his relationship with All For One, Yuga Aoyama calls himself a villain, but Deku tells him that he can still be a hero and reaches a hand out to him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612770.jpg"),
        array("id" => "s7e5", "season" => 7, "number" => 5, "name" => "Let You Down", "airdate" => "1 Jun 2024", "runtime" => 25, "rating" => 8.3, "summary" => "As heroes and villains get ready for the coming battle, Deku and the others leave U.A., and Deku is called out by Aoyama, who is supposed to be in a police cell. What does Aoyama want?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612771.jpg"),
        array("id" => "s7e6", "season" => 7, "number" => 6, "name" => "Division", "airdate" => "8 Jun 2024", "runtime" => 25, "rating" => 8.4, "summary" => "It's finally time for the decisive battle between heroes and villains! The plan by All Might, Aizawa, and the others has them start their fights in various places around Japan!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612782.jpg"),
        array("id" => "s7e7", "season" => 7, "number" => 7, "name" => "Inflation", "airdate" => "15 Jun 2024", "runtime" => 25, "rating" => 8, "summary" => "Even though Shigaraki's Quirks are sealed, he attacks Bakugo and the others with a strange new appearance and power. Meanwhile, Deku is pulled to where Toga was warped and Todoroki and Dabi face off!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612783.jpg"),
        array("id" => "s7e8", "season" => 7, "number" => 8, "name" => "Two Flashfires", "airdate" => "22 Jun 2024", "runtime" => 25, "rating" => 8.6, "summary" => "Eleven years ago, Toya Todoroki was burned by his own flames and became Dabi. Todoroki faces Dabi's blue flames with a new move of his own. Will he be able to stop his brother...?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612784.jpg"),
        array("id" => "s7e9", "season" => 7, "number" => 9, "name" => "Extras", "airdate" => "29 Jun 2024", "runtime" => 25, "rating" => 8.4, "summary" => "Shoto Todoroki stopped Dabi with his Great Glacial Aegir, and reports of that bolstered the spirits of the heroes fighting in other locations. And Shoto and Dabi's father, Endeavor, is facing the greatest evil, All For One, with Hawks!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612785.jpg"),
        array("id" => "s7e10", "season" => 7, "number" => 10, "name" => "Wounded Hero, Burning Bright and True!!", "airdate" => "13 Jul 2024", "runtime" => 25, "rating" => 9, "summary" => "Before the threat of All For One, Endeavor falls, and Hawks, Jiro, and Tokoyami are also cornered. Even so, Jiro acts like a hero! Endeavor is also encouraged after looking back at his own life.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612787.jpg"),
        array("id" => "s7e11", "season" => 7, "number" => 11, "name" => "Light Fades To Rain", "airdate" => "20 Jul 2024", "runtime" => 25, "rating" => 9, "summary" => "Bakugo's Howitzer Impact didn't work against Shigaraki/All For One, either, and Bakugo is pushed into a corner by Shigaraki's power and words. In order to get him out of that predicament, U.A.'s Big Three take a stand!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612788.jpg"),
        array("id" => "s7e12", "season" => 7, "number" => 12, "name" => "Those Who Defend, Those Who Violate", "airdate" => "3 Aug 2024", "runtime" => 25, "rating" => 8.7, "summary" => "Bakugo surprised Shigaraki/All For One with Cluster but was then cruelly pierced through. The heroes in all the different locations are getting pushed back... But even so, they will not give up!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612789.jpg"),
        array("id" => "s7e13", "season" => 7, "number" => 13, "name" => "A Chain of Events, Across the Ages", "airdate" => "17 Aug 2024", "runtime" => 25, "rating" => 9.1, "summary" => "Deku finally arrives at the Coffin in the Sky! Seeing Bakugo and the others defeated by Shigaraki/All For One, Deku shakes with anger. Can he control his feelings and win against Shigaraki? It's finally time for a showdown!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612801.jpg"),
        array("id" => "s7e14", "season" => 7, "number" => 14, "name" => "Together with Shoji", "airdate" => "24 Aug 2024", "runtime" => 25, "rating" => 8.7, "summary" => "Spinner takes heteromorphs who are exploding with resentment from being persecuted to Central Hospital to get Kurogiri back. Shoji, whose Quirk also makes him a heteromorph, shouts his feelings to them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612802.jpg"),
        array("id" => "s7e15", "season" => 7, "number" => 15, "name" => "Butterfly Effect", "airdate" => "31 Aug 2024", "runtime" => 25, "rating" => 8.1, "summary" => "Spinner and Present Mic both yell their hearts out. Will the one waking up to their voices be Kurogiri, or Shirakumo? Meanwhile, fighting Ochaco and the others on Okuto Island, Toga is finally going to use her secret weapon...!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612803.jpg"),
        array("id" => "s7e16", "season" => 7, "number" => 16, "name" => "The Chain Thus Far", "airdate" => "7 Sep 2024", "runtime" => 25, "rating" => 8.1, "summary" => "Toga consumed Twice's blood, and with Kurogiri's Warp, infinite doubles of Twice appear. Shigaraki's Decay is also released, and the heroes seem to be in a state of despair. But then, help comes from an unexpected quarter...", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612804.jpg"),
        array("id" => "s7e17", "season" => 7, "number" => 17, "name" => "Hopes", "airdate" => "14 Sep 2024", "runtime" => 25, "rating" => 8.4, "summary" => "With the addition of Gentle, La Brava, and Lady Nagant, Deku is able to restrain Shigaraki's hands and confront him on the ground. Meanwhile, at the Gunga Villa site, the rewound All For One shows off his awful power...", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612805.jpg"),
        array("id" => "s7e18", "season" => 7, "number" => 18, "name" => "It's a Small World", "airdate" => "21 Sep 2024", "runtime" => 25, "rating" => 8.6, "summary" => "Shishikura and the other members of Shiketsu High join the fight at the Gunga Villa site, and it's do-or-die as the heroes unite to fight back! But as All For One gets younger, he gets stronger. That's when unexpected backup arrives...!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612806.jpg"),
        array("id" => "s7e19", "season" => 7, "number" => 19, "name" => "I Am Here", "airdate" => "28 Sep 2024", "runtime" => 25, "rating" => 9.4, "summary" => "Trampling the heroes, All For One flies to become one with Shigaraki, and Dabi is about to explode with the heat he's been storing up in his body. Will the Symbol be able change this hopeless situation?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612807.jpg"),
        array("id" => "s7e20", "season" => 7, "number" => 20, "name" => "A Girl's Ego", "airdate" => "5 Oct 2024", "runtime" => 25, "rating" => 8.1, "summary" => "Toga transforms into Twice and backs the heroes into a corner with Infinite Doubles. In the midst of that, Ochaco does her best to get close to Toga to talk to her. How does Toga respond...?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612808.jpg"),
        array("id" => "s7e21", "season" => 7, "number" => 21, "name" => "Battle Without a Quirk", "airdate" => "12 Oct 2024", "runtime" => 25, "rating" => 8.9, "summary" => "Toga returns the smile of Ochaco, who tried to be friends with her. What does Toga do to the seriously-injured Ochaco? Meanwhile, All Might uses \"power\" developed by a friend to face All For One!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/645/1612809.jpg"),
    )),
